                }

                @Override
                public void onError(Throwable t) {
                    t.printStackTrace();
                }

                @Override
                public void onComplete() {
                    // no-op
                }
            };
            // DefaultSubscriber implements onStart() which is called by RxJava's subscribe()
            state.flowable.subscribe(subscriber);
        }
    }

    public enum Mode {

        FAST, SLOW
    }
