    public void setup() {
        // Simple source emitting a range of integers.
        source = Flowable.range(1, sourceSize);
        // Create the "other" publishers; each emits the same range synchronously.
        others = new Publisher<?>[otherCount];
        for (int i = 0; i < otherCount; i++) {
            others[i] = Flowable.range(1, sourceSize);
        }
        // Combiner that returns the source value (index 0) to keep work minimal.
        combiner = objects -> (Integer) objects[0];
    }

